package data;

import java.util.List;
import java.util.stream.Stream;

import jakarta.data.repository.CrudRepository;
import jakarta.data.repository.Query;
import jakarta.data.repository.Repository;
import jakarta.enterprise.context.SessionScoped;
import jakarta.enterprise.inject.Default;
import jakarta.inject.Named;

import model.Event;

/**
 * This is a basic DAO-like interface for use by JSF or EJB.
 * Original version was machine-generated by entitygen.
 * Methods are implemented for us by Apache DeltaSpike Data.
 * The methods in the inherited interface suffice for many apps!
 * @author Ian Darwin
 */
@Named("eventList") @Default
@SessionScoped
@Repository
public interface EventList extends CrudRepository<Event, Long> {

	@Query(value="select e from Event e where e.date >= now() order by e.date asc")
	Stream<Event> findAll();
}
